'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { InventoryCountBatch, InventoryCountRow, ItemWithOverride } from '@ims/types';
import { apiClient } from '@/lib/api-client';
import { ClipboardList, Save, CheckCircle, ChevronLeft, AlertTriangle } from 'lucide-react';
import Link from 'next/link';
import { cn } from '@/lib/utils';

export default function ActiveCountSessionPage() {
  const params = useParams();
  const router = useRouter();
  const batchId = params?.id as string;

  const [batch, setBatch] = useState<InventoryCountBatch | null>(null);
  const [rows, setRows] = useState<InventoryCountRow[]>([]);
  const [items, setItems] = useState<Record<string, ItemWithOverride>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isClosing, setIsClosing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Local state for actual counts before they are saved to the backend
  const [actualCounts, setActualCounts] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!batchId) return;

    const fetchData = async () => {
      try {
        setIsLoading(true);
        // Fetch batch details and items in parallel
        const [batchRes, itemsRes] = await Promise.all([
          apiClient<{ batch: InventoryCountBatch; rows: InventoryCountRow[] }>(`/inventory/counts/${batchId}`),
          apiClient<{ data: ItemWithOverride[] }>('/items?limit=1000')
        ]);

        setBatch(batchRes.batch);
        setRows(batchRes.rows);

        // Convert rows to local state map
        const initialCounts: Record<string, string> = {};
        batchRes.rows.forEach(r => {
          if (r.actualQty !== null && r.actualQty !== undefined) {
            initialCounts[r.id] = r.actualQty.toString();
          }
        });
        setActualCounts(initialCounts);

        // Convert items to map
        const itemsMap: Record<string, ItemWithOverride> = {};
        itemsRes.data.forEach(item => {
          itemsMap[item.id] = item;
        });
        setItems(itemsMap);
      } catch (err: any) {
        setError(err.message || 'Failed to load count session');
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [batchId]);

  const handleSaveRow = async (rowId: string) => {
    const value = actualCounts[rowId];
    if (value === undefined || value === '') return;

    const numValue = parseFloat(value);
    if (isNaN(numValue) || numValue < 0) return;

    try {
      setIsSaving(true);
      await apiClient(`/inventory/counts/${batchId}/rows/${rowId}`, {
        method: 'PATCH',
        body: { actualQty: numValue }
      });

      // Update local row state to reflect saved value
      setRows(prev => prev.map(r => r.id === rowId ? { ...r, actualQty: numValue } : r));
    } catch (err: any) {
      alert(err.message || 'Failed to save count');
    } finally {
      setIsSaving(false);
    }
  };

  const handleCloseBatch = async () => {
    if (!batch) return;

    // Check if any rows are missing actualQty in local state
    const missingCounts = rows.some(r => actualCounts[r.id] === undefined || actualCounts[r.id] === '');
    if (missingCounts) {
      if (!confirm('Some items have not been counted. They will be recorded with their expected quantities (variance of 0). Do you want to proceed?')) {
        return;
      }
    }

    try {
      setIsClosing(true);
      await apiClient(`/inventory/counts/${batchId}/close`, {
        method: 'POST',
        body: { version: batch.version }
      });
      router.push('/inventory/counts');
    } catch (err: any) {
      setError(err.message || 'Failed to close batch');
    } finally {
      setIsClosing(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-50 dark:bg-zinc-950">
        <div className="w-8 h-8 border-4 border-emerald-200 border-t-emerald-600 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (error || !batch) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-50 dark:bg-zinc-950 p-4">
        <div className="bg-red-50 text-red-600 p-6 rounded-2xl max-w-lg text-center">
          <AlertTriangle className="w-12 h-12 mx-auto mb-4 opacity-80" />
          <h2 className="text-xl font-bold mb-2">Error Loading Session</h2>
          <p>{error || 'Count batch not found'}</p>
          <Link href="/inventory/counts" className="mt-6 inline-block underline">Return to Counts</Link>
        </div>
      </div>
    );
  }

  const isOpen = batch.status === 'OPEN';

  return (
    <div className="min-h-screen bg-zinc-50 dark:bg-zinc-950 p-4 md:p-8 pb-32">
      <div className="max-w-4xl mx-auto space-y-6">

        <Link href="/inventory/counts" className="inline-flex items-center text-sm text-zinc-500 hover:text-zinc-900 dark:hover:text-white transition-colors">
          <ChevronLeft className="w-4 h-4 mr-1" />
          Back to Inventory Counts
        </Link>

        <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white dark:bg-zinc-900 p-6 rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-sm">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 bg-emerald-100 dark:bg-emerald-900/40 rounded-xl">
                <ClipboardList className="w-6 h-6 text-emerald-600 dark:text-emerald-400" />
              </div>
              <h1 className="text-2xl font-bold tracking-tight text-zinc-900 dark:text-white font-mono">
                Batch {batch.id.split('-')[0]}
              </h1>
              <span className={cn(
                "px-2.5 py-1 text-xs font-semibold rounded-md",
                isOpen ? "bg-amber-100 text-amber-700" : "bg-emerald-100 text-emerald-700"
              )}>
                {batch.status}
              </span>
            </div>
            <p className="text-sm text-zinc-500">
              Started on {new Date(batch.createdAt).toLocaleString()}
            </p>
          </div>

          {isOpen && (
            <button
              onClick={handleCloseBatch}
              disabled={isClosing}
              className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-sm font-medium transition-colors shadow-sm disabled:opacity-50"
            >
              {isClosing ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CheckCircle className="w-4 h-4" />}
              Reconcile & Close Batch
            </button>
          )}
        </header>

        <div className="bg-white dark:bg-zinc-900 rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-zinc-200 dark:divide-zinc-800">
              <thead className="bg-zinc-50 dark:bg-zinc-900/50">
                <tr>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-zinc-500 uppercase tracking-wider">Item</th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-zinc-500 uppercase tracking-wider">Expected Qty</th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-zinc-500 uppercase tracking-wider">Actual Qty</th>
                  {isOpen && <th scope="col" className="px-6 py-4 text-right text-xs font-semibold text-zinc-500 uppercase tracking-wider">Actions</th>}
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-200 dark:divide-zinc-800">
                {rows.map(row => {
                  const item = items[row.itemId];
                  const itemName = item ? item.name : `Unknown Item (${row.itemId.split('-')[0]})`;
                  const uom = item ? item.inventoryUom : '';
                  const hasUnsavedChanges = actualCounts[row.id] !== undefined && actualCounts[row.id] !== row.actualQty?.toString();
                  const isSaved = row.actualQty !== null;

                  return (
                    <tr key={row.id} className="hover:bg-zinc-50 dark:hover:bg-zinc-800/50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="text-sm font-medium text-zinc-900 dark:text-white">{itemName}</div>
                        <div className="text-xs text-zinc-500">{uom}</div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-sm text-zinc-600 dark:text-zinc-400 font-mono">
                          {row.expectedQty.toFixed(2)}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {isOpen ? (
                          <div className="flex items-center gap-2 max-w-xs">
                            <input
                              type="number"
                              min="0"
                              step="0.01"
                              value={actualCounts[row.id] ?? ''}
                              onChange={(e) => setActualCounts(prev => ({ ...prev, [row.id]: e.target.value }))}
                              onBlur={() => {
                                if (hasUnsavedChanges) handleSaveRow(row.id);
                              }}
                              className="w-24 px-3 py-1.5 border border-zinc-200 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-800 text-sm focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none font-mono"
                              placeholder="0.00"
                            />
                            {isSaved && !hasUnsavedChanges && <CheckCircle className="w-4 h-4 text-emerald-500" />}
                          </div>
                        ) : (
                          <span className={cn("text-sm font-mono font-semibold", row.actualQty !== row.expectedQty ? "text-amber-600" : "text-zinc-600 dark:text-zinc-400")}>
                            {row.actualQty !== null ? row.actualQty.toFixed(2) : '-'}
                          </span>
                        )}
                      </td>
                      {isOpen && (
                        <td className="px-6 py-4 text-right">
                          <button
                            onClick={() => handleSaveRow(row.id)}
                            disabled={!hasUnsavedChanges || isSaving}
                            className="inline-flex items-center justify-center p-2 text-zinc-500 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/30 rounded-lg transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                            title="Save Row"
                          >
                            <Save className="w-5 h-5" />
                          </button>
                        </td>
                      )}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { ItemWithOverride, PrepPlanResponse, PrepPlanLine } from '@ims/types';
import { apiClient } from '@/lib/api-client';
import { Calculator, ArrowLeft, CheckCircle2, AlertTriangle, AlertCircle } from 'lucide-react';

export default function PlanPrepPage() {
  const router = useRouter();
  const [items, setItems] = useState<ItemWithOverride[]>([]);
  const [selectedItemId, setSelectedItemId] = useState<string>('');
  const [targetYield, setTargetYield] = useState<number>(1);
  const [plan, setPlan] = useState<PrepPlanResponse | null>(null);

  const [isLoadingItems, setIsLoadingItems] = useState(true);
  const [isPlanning, setIsPlanning] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchItems = async () => {
      try {
        const res = await apiClient<{ data: ItemWithOverride[] }>('/items?limit=1000');
        setItems(res.data);
      } catch (err: any) {
        setError(err.message || 'Failed to load items');
      } finally {
        setIsLoadingItems(false);
      }
    };
    fetchItems();
  }, []);

  const handlePlan = React.useCallback(async () => {
    if (!selectedItemId || targetYield <= 0) return;

    setIsPlanning(true);
    setError(null);
    try {
      const res = await apiClient<{ data: PrepPlanResponse }>(`/inventory/prep/plan?itemId=${selectedItemId}&targetYield=${targetYield}`);
      setPlan(res.data);
    } catch (err: any) {
      setError(err.message || 'Failed to generate prep plan. Does this item have a recipe?');
      setPlan(null);
    } finally {
      setIsPlanning(false);
    }
  }, [selectedItemId, targetYield]);

  // Debounce the planning call
  useEffect(() => {
    const timeout = setTimeout(() => {
      if (selectedItemId && targetYield > 0) {
        handlePlan();
      } else {
        setPlan(null);
      }
    }, 500);
    return () => clearTimeout(timeout);
  }, [selectedItemId, targetYield, handlePlan]);

  const handleCommit = async () => {
    if (!plan || !plan.isPossible) return;
    if (plan.prepItemId !== selectedItemId || plan.targetYield !== targetYield) return; // Prevent race

    setIsSubmitting(true);
    try {
      await apiClient('/inventory/prep', {
        method: 'POST',
        body: {
          prepItemId: plan.prepItemId,
          yieldQtyProduced: plan.targetYield
        }
      });
      router.push('/inventory/prep');
      router.refresh();
    } catch (err: any) {
      setError(err.message || 'Failed to log prep batch');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-zinc-50 dark:bg-zinc-950 p-4 md:p-8">
      <div className="max-w-4xl mx-auto space-y-6">
        <header className="mb-6 flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <button 
              onClick={() => router.back()}
              className="p-2 text-zinc-500 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-200 dark:hover:bg-zinc-800 rounded-xl transition-colors"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex items-center space-x-3">
              <div className="p-2 bg-emerald-100 dark:bg-emerald-900/40 rounded-xl">
                <Calculator className="w-6 h-6 text-emerald-600 dark:text-emerald-400" />
              </div>
              <h1 className="text-3xl font-bold tracking-tight text-zinc-900 dark:text-white">
                Plan Production Batch
              </h1>
            </div>
          </div>
        </header>

        {error && (
          <div className="p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-2xl flex items-center gap-3">
            <AlertCircle className="w-5 h-5 flex-shrink-0" />
            <p className="text-sm font-medium">{error}</p>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-1 space-y-6 bg-white dark:bg-zinc-900 p-6 rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-sm h-fit">
            <h2 className="text-lg font-semibold text-zinc-900 dark:text-white">Batch Details</h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-1">Target Item</label>
                <select 
                  value={selectedItemId}
                  onChange={(e) => setSelectedItemId(e.target.value)}
                  disabled={isLoadingItems}
                  className="w-full px-3 py-2 border border-zinc-300 dark:border-zinc-700 rounded-xl bg-white dark:bg-zinc-800 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                >
                  <option value="">Select an item...</option>
                  {items.map(i => <option key={i.id} value={i.id}>{i.name} ({i.inventoryUom})</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-1">Target Yield Quantity</label>
                <input 
                  type="number" 
                  step="0.01" 
                  min="0.01"
                  value={targetYield || ''}
                  onChange={(e) => setTargetYield(parseFloat(e.target.value) || 0)}
                  className="w-full px-3 py-2 border border-zinc-300 dark:border-zinc-700 rounded-xl bg-white dark:bg-zinc-800 text-sm focus:ring-2 focus:ring-emerald-500 outline-none font-mono"
                />
              </div>
            </div>
          </div>

          <div className="md:col-span-2 space-y-6">
            <div className="bg-white dark:bg-zinc-900 rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-sm overflow-hidden">
              <div className="p-6 border-b border-zinc-200 dark:border-zinc-800 flex justify-between items-center">
                <h2 className="text-lg font-semibold text-zinc-900 dark:text-white">BOM Requirements</h2>
                {isPlanning && <span className="text-sm text-zinc-500 animate-pulse">Calculating...</span>}
              </div>

              {!plan ? (
                <div className="p-12 text-center text-zinc-500">
                  Select an item and quantity to preview required ingredients.
                </div>
              ) : (
                <>
                  <ul className="divide-y divide-zinc-200 dark:divide-zinc-800">
                    {plan.ingredients.map((ing) => (
                      <li key={ing.itemId} className="p-4 flex items-center justify-between hover:bg-zinc-50 dark:hover:bg-zinc-800/50 transition-colors">
                        <div>
                          <p className="font-medium text-zinc-900 dark:text-white">{ing.itemName}</p>
                          <p className="text-sm text-zinc-500">Stock: {ing.currentStock.toFixed(2)} {ing.inventoryUom}</p>
                        </div>
                        <div className="text-right">
                          <p className="font-mono font-semibold text-zinc-900 dark:text-white">
                            {ing.requiredQty.toFixed(2)} {ing.inventoryUom}
                          </p>
                          {ing.shortageQty > 0 && (
                            <p className="text-sm text-red-500 font-medium flex items-center justify-end gap-1 mt-1">
                              <AlertTriangle className="w-3 h-3" />
                              Missing {ing.shortageQty.toFixed(2)}
                            </p>
                          )}
                        </div>
                      </li>
                    ))}
                  </ul>
                  <div className={`p-4 border-t ${plan.isPossible ? 'bg-emerald-50 border-emerald-100 dark:bg-emerald-900/10 dark:border-emerald-900/20' : 'bg-red-50 border-red-100 dark:bg-red-900/10 dark:border-red-900/20'}`}>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        {plan.isPossible ? (
                          <CheckCircle2 className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
                        ) : (
                          <AlertTriangle className="w-5 h-5 text-red-600 dark:text-red-400" />
                        )}
                        <span className={`font-medium ${plan.isPossible ? 'text-emerald-700 dark:text-emerald-400' : 'text-red-700 dark:text-red-400'}`}>
                          {plan.isPossible ? 'Stock Sufficient' : 'Insufficient Stock'}
                        </span>
                      </div>

                      <button
                        onClick={handleCommit}
                        disabled={!plan.isPossible || isSubmitting}
                        className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:hover:bg-emerald-600 text-white text-sm font-medium rounded-xl transition-colors shadow-sm"
                      >
                        {isSubmitting ? 'Committing...' : 'Commit Production'}
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { Loader2, Fingerprint } from 'lucide-react';
import { RestaurantSelector } from '@/components/auth/restaurant-selector';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(true); // Start true to check existing session
  const [submitting, setSubmitting] = useState(false); // True only while form is submitting
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // Controls the flow: false = Login Form, true = Restaurant Selector
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Auto-detect existing session: if the user is already logged in with Supabase
  // (e.g., they were redirected here because restaurantId was null),
  // skip the login form and show the restaurant selector directly.
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        setIsAuthenticated(true);
      }
      setLoading(false);
    });
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    setMessage(null);

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) {
        throw error;
      }

      setIsAuthenticated(true);
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-50 dark:bg-zinc-950 p-4 relative overflow-hidden">

      {/* Background decoration */}
      <div className="absolute top-[-10%] left-[-10%] w-96 h-96 bg-blue-500/20 dark:bg-blue-500/10 blur-3xl rounded-full mix-blend-multiply dark:mix-blend-lighten pointer-events-none" />
      <div className="absolute bottom-[-10%] right-[-10%] w-[30rem] h-[30rem] bg-indigo-500/20 dark:bg-indigo-500/10 blur-3xl rounded-full mix-blend-multiply dark:mix-blend-lighten pointer-events-none" />

      <div className="relative z-10 max-w-md w-full bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl p-8 rounded-3xl shadow-2xl border border-white/20 dark:border-zinc-800/50">

        {/* Header Icon */}
        <div className="flex justify-center mb-6">
          <div className="p-3 bg-blue-100 dark:bg-blue-900/50 rounded-2xl text-blue-600 dark:text-blue-400">
            <Fingerprint className="w-8 h-8" />
          </div>
        </div>

        {loading ? (
          // Initial session check — show spinner to prevent flash of login form
          <div className="flex flex-col items-center justify-center py-8 space-y-3 text-zinc-500">
            <Loader2 className="w-8 h-8 animate-spin" />
            <p className="text-sm">Checking session...</p>
          </div>
        ) : !isAuthenticated ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h1 className="text-2xl font-bold text-center text-zinc-900 dark:text-white mb-2">
              Welcome back
            </h1>
            <p className="text-center text-sm text-zinc-500 dark:text-zinc-400 mb-8">
              Sign in to Synculariti OS IMS
            </p>

            <form onSubmit={handleLogin} className="space-y-5">
              <div className="space-y-1.5">
                <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300">
                  Email
                </label>
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-4 py-3 bg-white/50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none dark:text-white transition-all placeholder:text-zinc-400"
                  placeholder="name@example.com"
                />
              </div>

              <div className="space-y-1.5">
                <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300">
                  Password
                </label>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-4 py-3 bg-white/50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none dark:text-white transition-all placeholder:text-zinc-400"
                  placeholder="••••••••"
                />
              </div>

              <button
                type="submit"
                disabled={submitting}
                className="w-full flex items-center justify-center py-3 px-4 bg-zinc-900 hover:bg-zinc-800 dark:bg-white dark:hover:bg-zinc-100 dark:text-zinc-900 text-white font-medium rounded-xl transition-all disabled:opacity-50 mt-4 shadow-md"
              >
                {submitting ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Continue'}
              </button>
            </form>

            {message && (
              <div className={`mt-6 p-4 rounded-xl text-sm text-center font-medium border ${message.type === 'success' ? 'bg-emerald-50 border-emerald-200 text-emerald-700 dark:bg-emerald-900/20 dark:border-emerald-800/50 dark:text-emerald-400' : 'bg-red-50 border-red-200 text-red-700 dark:bg-red-900/20 dark:border-red-800/50 dark:text-red-400'}`}>
                {message.text}
              </div>
            )}
          </div>
        ) : (
          <RestaurantSelector />
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { authApi } from '@/lib/api/auth';
import { User, Shield, Save, CheckCircle } from 'lucide-react';

export default function ProfilePage() {
  const [profile, setProfile] = useState<any>(null);
  const [fullName, setFullName] = useState('');
  const [phone, setPhone] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    authApi.getMe().then(res => {
      setProfile(res);
      setFullName(res.fullName || '');
      setPhone(res.phoneNumber || '');
    });
  }, []);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await authApi.updateProfile({ full_name: fullName, phone_number: phone });
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSaving(false);
    }
  };

  if (!profile) return <div className="p-12 text-center text-zinc-500">Loading profile...</div>;

  return (
    <div className="max-w-3xl mx-auto p-6 mt-10">
      <div className="flex items-center gap-3 mb-8">
        <div className="w-12 h-12 rounded-2xl bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center text-indigo-600 dark:text-indigo-400">
          <User className="w-6 h-6" />
        </div>
        <div>
          <h1 className="text-3xl font-bold text-zinc-900 dark:text-white">Profile Settings</h1>
          <p className="text-zinc-500">{profile.email}</p>
        </div>
      </div>

      <div className="bg-white dark:bg-zinc-900 rounded-3xl border border-zinc-200 dark:border-zinc-800 p-8 shadow-sm space-y-6">
        <div>
          <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-2">Full Name</label>
          <input type="text" value={fullName} onChange={e => setFullName(e.target.value)} className="w-full max-w-md px-4 py-2 bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none" />
        </div>
        <div>
          <label className="block text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-2">Phone Number</label>
          <input type="tel" value={phone} onChange={e => setPhone(e.target.value)} className="w-full max-w-md px-4 py-2 bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none" />
        </div>

        <div className="pt-4 flex items-center gap-4">
          <button onClick={handleSave} disabled={isSaving} className="px-6 py-2.5 bg-indigo-600 text-white rounded-xl font-medium hover:bg-indigo-700 transition-colors disabled:opacity-50 flex items-center gap-2">
            {isSaving ? 'Saving...' : <><Save className="w-4 h-4" /> Save Changes</>}
          </button>
          {success && <span className="text-emerald-600 flex items-center gap-1.5 text-sm"><CheckCircle className="w-4 h-4" /> Saved successfully</span>}
        </div>
      </div>

      <div className="mt-8 bg-zinc-50 dark:bg-zinc-900/50 rounded-3xl border border-zinc-200 dark:border-zinc-800 p-8">
        <h3 className="text-lg font-semibold flex items-center gap-2 mb-4">
          <Shield className="w-5 h-5 text-indigo-500" />
          Active Permissions
        </h3>
        <div className="flex flex-wrap gap-2">
          {profile.permissions?.map((p: string) => (
            <span key={p} className="px-3 py-1 bg-zinc-200 dark:bg-zinc-800 text-zinc-800 dark:text-zinc-300 rounded-lg text-xs font-mono">{p}</span>
          ))}
          {!profile.permissions?.length && <span className="text-zinc-500 text-sm">No specific permissions assigned.</span>}
        </div>
      </div>
    </div>
  );
}

