      apiClient<{ data: ItemWithOverride[] }>('/items?limit=1000')
        .then(res => setItems(res.data))
        .catch(console.error);
    }
  }, [open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
