  const [isGeneratingSku, setIsGeneratingSku] = useState(false);

  const {
    register,
    handleSubmit,
    reset,
    watch,
    setValue,
    formState: { errors },
  } = useForm<UpdateItemForm>({
    resolver: zodResolver(updateItemSchema),
    defaultValues: {
      name: '',
      type: 'RAW' as const,
      sku: '',
      purchasingUom: 'kg',
      inventoryUom: 'kg',
      recipeUom: null,
      invToRecipeRatio: 1,
      isActive: true,
      categoryId: '',
    },
  });

  const itemType = watch('type');

  useEffect(() => {
    if (item) {
      reset({
        name: item.name,
        type: item.type as 'RAW' | 'PREP',
        sku: item.sku,
        purchasingUom: item.purchasingUom,
        inventoryUom: item.inventoryUom,
        recipeUom: item.recipeUom,
        invToRecipeRatio: item.invToRecipeRatio,
        isActive: item.isActive,
        categoryId: item.categoryId || '',
      });

      const fetchCategories = async () => {
        try {
          setIsLoadingCategories(true);
          const res = await apiClient<{ data: Category[] }>('/items/categories');
          setCategories(res.data || []);
        } catch (error) {
          console.error('Failed to fetch categories:', error);
        } finally {
          setIsLoadingCategories(false);
        }
      };
      fetchCategories();
    }
  }, [item, reset]);

  if (!item) return null;

  const onSubmit = async (data: UpdateItemForm) => {
    setIsSubmitting(true);
    setError(null);
    try {
      await apiClient(`/items/${item.id}`, {
