      setIsLoading(true);
      const res = await procurementApi.listVendors();
      setVendors(res.data || []);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchVendors();
  }, []);

