import { ItemWithOverride, Category } from '@ims/types';

export const itemApi = {
  listItems: async () => apiClient<{ data: ItemWithOverride[] }>('/items'),
  createItem: async (dto: any) => apiClient<any>('/items', { method: 'POST', body: dto }),
  updateItem: async (id: string, dto: any) => apiClient<any>(`/items/${id}`, { method: 'PUT', body: dto }),
  deleteItem: async (id: string) => apiClient<any>(`/items/${id}`, { method: 'DELETE' }),
  listCategories: async () => apiClient<{ data: Category[] }>('/items/categories'),
  updateOverride: async (id: string, dto: any) => apiClient<any>(`/items/${id}/overrides`, { method: 'PATCH', body: dto }),
  upsertUomConversion: async (dto: any) => apiClient<any>('/items/uom-conversions', { method: 'POST', body: dto }),
};

import { apiClient } from '../api-client';
import { PurchaseOrder, Vendor } from '@ims/types';
import { CreatePoDto, CreateVendorDto } from '@ims/validators';

export const procurementApi = {
  createDraftPO: async (dto: CreatePoDto) => {
    return apiClient<PurchaseOrder>('/procurement/orders', { method: 'POST', body: dto });
  },
  submitPO: async (id: string) => {
    return apiClient<PurchaseOrder>(`/procurement/orders/${id}/submit`, { method: 'PATCH' });
  },
  cancelPO: async (id: string) => {
    return apiClient<void>(`/procurement/orders/${id}/cancel`, { method: 'PATCH' });
  },
  listVendors: async () => {
    return apiClient<{ data: Vendor[] }>('/procurement/orders/vendors');
  },
  createVendor: async (dto: CreateVendorDto) => {
    return apiClient<Vendor>('/procurement/orders/vendors', { method: 'POST', body: dto });
  },
  updateVendor: async (id: string, dto: any) => {
    return apiClient<Vendor>(`/procurement/orders/vendors/${id}`, { method: 'PUT', body: dto });
  }
};

import { apiClient } from '../api-client';

export const tenantApi = {
  listRestaurants: async () => apiClient<{ data: any[] }>('/tenant/restaurants'),
  createRestaurant: async (dto: any) => apiClient<any>('/tenant/restaurants', { method: 'POST', body: dto }),
  updateRestaurant: async (id: string, dto: any) => apiClient<any>(`/tenant/restaurants/${id}`, { method: 'PUT', body: dto }),
  listFranchises: async () => apiClient<{ data: any[] }>('/tenant/franchise-groups'),
};
